import{_ as a,o as s,c as t,a3 as o}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse('{"title":"Screens","description":"","frontmatter":{},"headers":[],"relativePath":"use/screens.md","filePath":"use/screens.md"}'),r={name:"use/screens.md"};function n(i,e,h,d,c,l){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="screens" tabindex="-1">Screens <a class="header-anchor" href="#screens" aria-label="Permalink to &quot;Screens&quot;">​</a></h1><p>Wake&#39;s web app follows each project live: what your agents do appears while they do it, without reloading. Open it at <code>&lt;your Wake URL&gt;</code>. The words it uses, such as phase, claim and evidence, are explained in <a href="/wake-dist/docs/start/concepts">Concepts</a>.</p><h2 id="tracking" tabindex="-1">Tracking <a class="header-anchor" href="#tracking" aria-label="Permalink to &quot;Tracking&quot;">​</a></h2><p>What is in progress right now (on track, late or stale), the percentage done, the pace, the estimated finish, the newest version and the latest changes. When the repository groups its changes into <a href="/wake-dist/docs/agents/milestones">milestones</a>, the milestones run along the top, with the one you are in marked.</p><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><p>A Gantt chart of every phase and task: real durations for finished and in-progress work, and an estimated schedule for the rest. Committed plans (from the default branch) and provisional plans (from other branches) look different. Search for a task, group the plan by deliverables or teams, and zoom from the whole plan down to six hours.</p><h2 id="team" tabindex="-1">Team <a class="header-anchor" href="#team" aria-label="Permalink to &quot;Team&quot;">​</a></h2><p>Who, and which agent <a href="/wake-dist/docs/start/concepts#session">session</a>, works on what: the elapsed time, the time left, <a href="/wake-dist/docs/start/concepts#claim">claims</a> gone stale that need a decision, and the feed of claims.</p><h2 id="task-detail" tabindex="-1">Task detail <a class="header-anchor" href="#task-detail" aria-label="Permalink to &quot;Task detail&quot;">​</a></h2><p>Open any task to see what it includes, when it is done, its verification, its dates and dependencies, its commits with the lines changed per area, the tool calls its sessions made, and its <a href="/wake-dist/docs/start/concepts#evidence">evidence</a> files, such as screenshots and logs.</p><h2 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h2><p>Every version tag, newest first, with the tasks it released, grouped by phase with their commits, and how to check it out. See <a href="/wake-dist/docs/use/versions">Versions and tags</a>.</p><h2 id="archived-projects" tabindex="-1">Archived projects <a class="header-anchor" href="#archived-projects" aria-label="Permalink to &quot;Archived projects&quot;">​</a></h2><p>Choose <strong>Archive project</strong> from the <strong>⋯</strong> project menu next to the project switcher to take a project out of the lists. An archived project refuses every change until it is restored; opening it shows it read-only under a banner. <strong>Archived projects</strong>, in the project switcher, lists them, each with <strong>Restore</strong>.</p><h2 id="the-header" tabindex="-1">The header <a class="header-anchor" href="#the-header" aria-label="Permalink to &quot;The header&quot;">​</a></h2><ul><li>The project switcher picks the project, creates one (<strong>New project</strong>) or opens the archived ones.</li><li><strong>Agents</strong> shows the agent sessions working on the project, and which are idle.</li><li><strong>Members</strong> lists the people in the workspace: see <a href="/wake-dist/docs/use/workspaces">Workspaces and roles</a>. Owners also find the <a href="/wake-dist/docs/use/audit-log">audit log</a> there.</li><li><strong>Tokens</strong> lists your personal access tokens: see <a href="/wake-dist/docs/use/tokens">Tokens</a>.</li><li>The round button with your initial opens <strong>Account</strong>: see <a href="/wake-dist/docs/use/account">Your account</a>.</li><li>Theme (system, light or dark) and language (English or Spanish).</li></ul><p>When a newer stable release of Wake exists, signed-in people see a banner with its release notes and the upgrade guide; see <a href="/wake-dist/docs/run/upgrade#how-you-hear-of-a-new-release">How you hear of a new release</a>.</p>',17)])])}const g=a(r,[["render",n]]);export{u as __pageData,g as default};
